#!/usr/bin/env python3

from loguru import logger
from util import state_file as state, variables as var
from util.launch_opt.editor import add_launch_option, remove_launch_option


def add_launch_opt():
    launcher = state.current_instance.launcher
    game_id = getattr(state.current_instance.launcher_ids, launcher, None)
    if launcher and game_id:
        label = "Mod Organizer"
        if not launcher == "steam":
            label = "Launch " + label
        launch_index = add_launch_option(
            launcher=launcher,
            game_id=game_id,
            executable="mo2-redirector.exe",
            arguments=var.game_info.launch_options.get("arguments", [])
            if var.game_info.launch_options
            and "arguments" in var.game_info.launch_options
            else [],
            label=var.game_info.launch_options.get("label", label)
            if var.game_info.launch_options and "label" in var.game_info.launch_options
            else label,
            game_path=str(state.current_instance.game_path)
            if state.current_instance.game_path
            else None,
            opt_type=var.game_info.launch_options.get("type", "OPTION3")
            if var.game_info.launch_options and "type" in var.game_info.launch_options
            else "OPTION3",
            oslist=var.game_info.launch_options.get("oslist", None)
            if var.game_info.launch_options and "oslist" in var.game_info.launch_options
            else None,
            osarch=var.game_info.launch_options.get("osarch", None)
            if var.game_info.launch_options and "osarch" in var.game_info.launch_options
            else None,
        )
        if launcher == "steam" and launch_index is not None:
            state.current_instance.launch_option_index = launch_index
            # Store the launch option type for Steam URL protocol
            state.current_instance.launch_option_type = (
                var.game_info.launch_options.get("type", "OPTION3")
                if var.game_info.launch_options
                else "OPTION3"
            )
        logger.info(f"Added launch option for {launcher} game ID {game_id}")
    else:
        logger.warning(
            f"Launcher '{launcher}' is not supported for launch options, or launcher ID is missing"
        )


def remove_launch_opt():
    launcher = state.current_instance.launcher
    game_id = getattr(state.current_instance.launcher_ids, launcher, None)
    if launcher and game_id:
        if (
            launcher == "steam"
            and state.current_instance.launch_option_index is not None
        ):
            remove_launch_option(
                launcher=launcher,
                game_id=game_id,
                index=state.current_instance.launch_option_index,
            )
        elif launcher == "epic":
            remove_launch_option(
                launcher=launcher,
                game_id=game_id,
                label="Launch Mod Organizer",
            )
        elif launcher == "gog":
            remove_launch_option(
                launcher=launcher,
                game_id=game_id,
                game_path=str(state.current_instance.game_path)
                if state.current_instance.game_path
                else None,
                label="Launch Mod Organizer",
            )
        logger.info(f"Removed launch option for {launcher} game ID {game_id}")
    else:
        logger.warning(
            f"Launcher '{launcher}' is not supported for launch options, or launcher ID is missing"
        )

    def __post_init__(self):
        if not (self.steam or self.gog or self.epic):
            logger.critical(
                "LauncherIDs: At least one of 'steam', 'gog', or 'epic' parameters must be provided."
            )
            logger.critical(
                "This should not happen. Please report this to the developer."
            )
            raise SystemExit(1)


@dataclass
class AppInfo:
    """
    Data class for storing appinfo.vdf data for a specific game.

    Parameters
    -----------
    index : int
        Numeric index for the launch option.
    executable : str
        Path to the desired executable, relative to the game's install directory. Default is "mo2-redirector.exe".
    arguments : list[str], optional
        List of launch arguments to use with the executable.
    type : str, optional
        Type of launch option (e.g., "default", "none", "vr", "server", "OPTION1", "OPTION2", "OPTION3"). Default is "OPTION3".
    oslist : list[str], optional
        List of operating systems the launch option is valid for. e.g. 'windows', 'linux', 'macos'.
    osarch : str, optional
        OS architecture the launch option is valid for (e.g., "32", "64").
    description : str, optional
        Label for the launch option, shown in the Steam UI.
    """

    index: int = -1
    executable: str = "mo2-redirector.exe"
    arguments: Optional[List[str]] = None
    type: str = "OPTION3"
    oslist: List[str] = None
    osarch: Optional[str] = None
    description: Optional[str] = None
    description_loc: Optional[dict[str, str]] = None

    @classmethod
    def from_dict(cls, data: dict, index: int = None) -> "AppInfo":
        return cls(
            index=index,
            executable=data.get("executable", "mo2-redirector.exe"),
            arguments=data.get("arguments") or None,
            type=data.get("type", "none"),
            oslist=data.get("oslist", []),
            osarch=data.get("osarch") or (data.get("config", {}).get("osarch") or None),
            description=data.get("description") or None,
            description_loc=data.get("description_loc") or None,
        )

    @classmethod
    def to_dict(cls, data: "AppInfo") -> dict[str, any]:
        result = {
            "index": data.index,
            "executable": data.executable,
            "arguments": data.arguments,
            "type": data.type,
        }
        if data.description:
            result["description"] = data.description
        if data.description_loc:
            result["description_loc"] = data.description_loc
        if data.osarch:
            result["config"] = {
                "oslist": data.oslist,
                "osarch": data.osarch,
            }
        else:
            result["config"] = {
                "oslist": data.oslist,
            }

        return result


